 model: PrismaModelDelegate, // Ej: prisma.user\n  ) {\n    this.model = model;\n  }\n\n  async findMany(params?: unknown): Promise {\n    return await this.model.findMany(params);\n  }\n\n  async findUnique(params: unknown): Promise {\n    return await this.model.findUnique(params);\n  }\n\n  async findFirst(params?: unknown): Promise {\n    return await this.model.findFirst(params);\n  }\n\n  async create(data: unknown): Promise {\n    return await this.model.create({ data });\n  }\n\n  async createMany(data: unknown[]): Promise {\n    return await this.model.createMany({ data });\n  }\n\n  async update(params: unknown): Promise {\n    return await this.model.update(params);\n  }\n\n  async updateMany(params: unknown): Promise {\n    return await this.model.updateMany(params);\n  }\n\n  async upsert(params: unknown): Promise {\n    return await this.model.upsert(params);\n  }\n\n  async delete(params: unknown): Promise {\n    return await this.model.delete(params);\n  }\n\n  async deleteMany(params?: unknown): Promise {\n    return await this.model.deleteMany(params);\n  }\n\n  async count(params?: unknown): Promise {\n    return await this.model.count(params);\n  }\n\n  async aggregate(params?: unknown): Promise {\n    return await this.model.aggregate(params);\n  }\n\n  async groupBy(params: unknown): Promise {\n    return await this.model.groupBy(params);\n  }\n\n  async rawQuery(query: string, params?: unknown[]): Promise {\n    return await this.prisma.$queryRawUnsafe(query, ...(params || []));\n  }\n\n  async rawExecute(query: string, params?: unknown[]): Promise {\n    return await this.prisma.$executeRawUnsafe(query, ...(params || []));\n  }\n}\n\n    \n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n"},"classes/PrismaBaseService.html":{"url":"classes/PrismaBaseService.html","title":"class - PrismaBaseService","body":"\n                   \n\n\n\n\n\n\n\n\n\n\n\n